    Sendbar[] dienste = new Sendbar[2];
    dienste[0] = new Email();
    dienste[1] = new SMS();
    for (int i = 0; i < dienste.length; i++) {
      dienste[i].sende("Hallo");
    }
    dienste[0].sende("Test");
    for (int i = 0; i < dienste.length; i++) {
      if (dienste[i] instanceof Protokollierbar) {
