interface Sendbar {
  void sende(String text);
}

interface Protokollierbar {
  String protokoll();
}

class Email implements Sendbar, Protokollierbar {
  private int gesendet = 0;
  public void sende(String text) {
    System.out.println("E-Mail: " + text);
    gesendet++;
  }
  public String protokoll() {
    return "E-Mail hat " + gesendet + " Nachricht(en) gesendet";
  }
}

class SMS implements Sendbar {
  public void sende(String text) {
    System.out.println("SMS: " + text);
  }
}

